CREATE TABLE negocios(id INT AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120),tipo VARCHAR(30),fe_activa TINYINT DEFAULT 0,fe_url VARCHAR(255),fe_token VARCHAR(255),creado TIMESTAMP DEFAULT CURRENT_TIMESTAMP)ENGINE=InnoDB;
CREATE TABLE usuarios(id INT AUTO_INCREMENT PRIMARY KEY,negocio_id INT,nombre VARCHAR(80),email VARCHAR(120) UNIQUE,clave VARCHAR(255),rol ENUM('dueno','vendedor') DEFAULT 'vendedor')ENGINE=InnoDB;
CREATE TABLE productos(id INT AUTO_INCREMENT PRIMARY KEY,negocio_id INT,nombre VARCHAR(120),codigo VARCHAR(60),precio INT,costo INT DEFAULT 0,stock INT DEFAULT 0,minimo INT DEFAULT 3,activo TINYINT DEFAULT 1,INDEX(negocio_id))ENGINE=InnoDB;
CREATE TABLE clientes(id INT AUTO_INCREMENT PRIMARY KEY,negocio_id INT,nombre VARCHAR(100),telefono VARCHAR(30),deuda INT DEFAULT 0,INDEX(negocio_id))ENGINE=InnoDB;
CREATE TABLE ventas(id INT AUTO_INCREMENT PRIMARY KEY,negocio_id INT,usuario_id INT,cliente_id INT NULL,total INT,descuento INT DEFAULT 0,metodo VARCHAR(20),fe_estado VARCHAR(20) NULL,fe_resp TEXT NULL,creado TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(negocio_id,creado))ENGINE=InnoDB;
CREATE TABLE venta_items(id INT AUTO_INCREMENT PRIMARY KEY,venta_id INT,producto_id INT,nombre VARCHAR(120),cantidad INT,precio INT,INDEX(venta_id))ENGINE=InnoDB;
CREATE TABLE compras(id INT AUTO_INCREMENT PRIMARY KEY,negocio_id INT,proveedor VARCHAR(100),producto_id INT,cantidad INT,costo INT,creado TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(negocio_id))ENGINE=InnoDB;
CREATE TABLE pagos(id INT AUTO_INCREMENT PRIMARY KEY,negocio_id INT,cliente_id INT,monto INT,creado TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(negocio_id))ENGINE=InnoDB;
CREATE TABLE cierres(id INT AUTO_INCREMENT PRIMARY KEY,negocio_id INT,usuario_id INT,desde DATETIME,hasta DATETIME,esperado INT,contado INT,INDEX(negocio_id))ENGINE=InnoDB;
ALTER TABLE productos ADD iva TINYINT DEFAULT 0, ADD vence DATE NULL;
ALTER TABLE negocios ADD usa_vence TINYINT DEFAULT 0, ADD meta INT DEFAULT 0;
ALTER TABLE usuarios ADD super TINYINT DEFAULT 0;
ALTER TABLE ventas ADD anulada TINYINT DEFAULT 0;
ALTER TABLE venta_items ADD costo INT DEFAULT 0, ADD iva TINYINT DEFAULT 0;
CREATE TABLE gastos(id INT AUTO_INCREMENT PRIMARY KEY,negocio_id INT,concepto VARCHAR(120),monto INT,creado TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(negocio_id))ENGINE=InnoDB;
CREATE TABLE recuperaciones(id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(120),token VARCHAR(64),expira DATETIME,INDEX(token))ENGINE=InnoDB;
